package com.fixmycity.issue;
import jakarta.persistence.*; import java.time.Instant;
@Entity public class IssueUpdate { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private Issue issue; @Enumerated(EnumType.STRING) private IssueStatus status; @Column(length=600) private String note; private String author; private Instant createdAt=Instant.now(); protected IssueUpdate(){} public IssueUpdate(Issue issue, IssueStatus status, String note, String author){this.issue=issue;this.status=status;this.note=note;this.author=author;} public Long getId(){return id;} public IssueStatus getStatus(){return status;} public String getNote(){return note;} public String getAuthor(){return author;} public Instant getCreatedAt(){return createdAt;} }
